 for p in (C/'jobs').glob('*.result.json'):
  e=read(p);assert e['exit_code']==0
  for pid,ticks in [(e['pid'],e['proc_start_ticks'])]+[(v['pid'],v['proc_start_ticks']) for v in e.get('CPU_child_identities',[])]:
   path=Path('/proc')/str(pid)/'stat';alive=path.exists() and path.read_text().split()[2]!='Z' and path.read_text().split()[21]==ticks;assert not alive,(pid,'Owned worker alive')
  records.append({'pid':e['pid'],'start_ticks':e['proc_start_ticks'],'exit_code':e['exit_code'],'command_sha256':e['command_sha256']})
  active=p.with_name(p.name.removesuffix('.result.json')+'.active.json')
  if active.exists() and read(active).get('status')=='RUNNING':
   snapshot=active.with_name(active.stem+'.running-snapshot.json')
   if not snapshot.exists():atomic(snapshot,active.read_bytes())
   put(active,e|{'status':'EXIT_CONFIRMED','reconciled_from_immutable_exit_record':True})
 assert len(list((C/'jobs').glob('*.json')))>0
 specs=[p for p in (C/'jobs').glob('*.json') if not any(s in p.name for s in ['.active.','.result.','.running-snapshot.'])]
 assert len(specs)==len(records)
 locks=list((A/'locks').rglob('*.lock'))+[R/'REPOSITORY_DELIVERY.lock']
 for p in locks:
  if p.exists():
   with p.open('r') as f:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);fcntl.flock(f,fcntl.LOCK_UN)
 return state|{'all_owned_jobs_exit_confirmed':records,'all_owned_locks_free':True,'lock_files_checked':len(locks)}

